{
  /** 到期提示：轻量、可拒绝 */
  promptQuestion: '有一个之前容易混淆的知识点，要不要花几十秒再看一眼？',
  promptNow: '复习一下',
  promptLater: '现在不方便',

  /** 选择"现在不方便"之后的中性回应（不惩罚、不清零、不留红点） */
  laterAck: '好，那就不看。它还在"值得再看一眼"里，你想起来的时候随时可以翻。',

  /** 复习卡片上的两个按钮 */
  recalledLabel: '想起来了',
  againLabel: '再看一遍',

  /** 两种结果的回应，都不给评价 */
  recalledAck: '这个点你已经能自己说清楚了。',
  againAck: '没关系，再看一遍就是它存在的意义。',

  /** 复习区标题与描述 */
  sectionTitle: '值得再看一眼',
  sectionDesc: '这里放的是一些容易混淆的点。不用清空，也不用按顺序看。',
  dueBadge: '今天可以看',
  scheduledBadge: (days) => (days <= 1 ? '明天可以看' : `约 ${days} 天后可以看`),
  emptyNote: '现在没有需要复习的内容。',
}
